text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "整体销售概况统计",
      "business_question": "这份销售数据的总订单数、总销售额及平均单笔销售额是多少？",
      "priority": "P0",
      "priority_reason": "删除此任务将无法建立数据基线，无法回答核心问题中关于“主要特征”的最基本量化描述。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_orders"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales_amount"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_order_value"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "地区维度差异分析",
      "business_question": "不同地区的订单数量和销售额分布有何差异？哪个地区表现最突出？",
      "priority": "P0",
      "priority_reason": "探索“差异”的核心在于关键业务维度（地区）的对比，删除后无法识别地域性特征。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "region_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "region_total_sales"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "region_total_sales",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "产品类别结构分析",
      "business_question": "各产品类别的销售贡献度如何？哪类产品是主要的收入来源？",
      "priority": "P1",
      "priority_reason": "补充性分析，帮助理解业务构成特征，虽非唯一核心但能显著增强对“主要特征”的理解深度。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "category_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "category_total_sales"
              }
            ],
            "dimensions": [
              "field_0007"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "category_total_sales",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T04",
      "title": "时间趋势初步观察",
      "business_question": "按年份和月份查看销售记录的时间分布特征是什么？",
      "priority": "P2",
      "priority_reason": "仅10行数据且无明确时间范围约束，时间规律可能不显著，作为补充视角提供数据覆盖度的直观感受。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "derive",
          "params": {
            "function": "extract_year",
            "field": "field_0001",
            "alias": "order_year"
          }
        },
        {
          "step_id": "S02",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "order_month"
          }
        },
        {
          "step_id": "S03",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "monthly_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "monthly_sales_amount"
              }
            ],
            "dimensions": [
              "order_year",
              "order_month"
            ]
          }
        }
      ]
    }
  ]
}
